private void xrTableCell5_SummaryGetResult(object sender, SummaryGetResultEventArgs e)
        {
            double shuma = 0;
            for (int i = 0; i < e.CalculatedValues.Count; i++)
                shuma += double.Parse(e.CalculatedValues[i].ToString());
            if (shuma >= 0){
                e.Result = shuma;
			debiParaSintetike += shuma;
		}else e.Result = "";
            e.Handled = true;
        }

