        private void xrTableCell18_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
        {
            if (GetCurrentColumnValue("levizja") != null)
            {
                double vlera = Convert.ToDouble(GetCurrentColumnValue("levizja"));
                if (vlera < 0)
                    xrTableCell28.Text = String.Format("{0:#,#.00}", Math.Abs(vlera));
                else
                    xrTableCell28.Text = String.Format("{0:#,#.00}", vlera);
            }
        }

