string scopeID ;
private void Rap_KontGjendjaLlogariMastro_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) { 
	var  parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);
	var filtrat = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]); 
	scopeID = parametraRaporti.ScopeID;

	foreach (var filter in filtrat)
    	 {
      	if (filter.Emri == "filterLlogariSintetike"){ 
        		if(filter.Vlera.ToString() == "Po"){
				this.Parameters["sintetike"].Value = true;
			}else{
				this.Parameters["sintetike"].Value = false;
			}
		}
	}

xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);

}


